diff --git a/apps/web/src/presentation/guest-meeting/devices/device-copy.ts b/apps/web/src/presentation/guest-meeting/devices/device-copy.ts
new file mode 100644
index 00000000..f70ad0cf
--- /dev/null
+++ b/apps/web/src/presentation/guest-meeting/devices/device-copy.ts
@@ -0,0 +1,63 @@
+// TJ-ARCH-MOB-001 compliant
+// Copy for the device pickers in the lobby and the room's "Audio and video" pane
+// (device-settings shape, sections 6 and 7). Plain and calm; errors give the cause, then
+// the fix. Domain and application carry codes only.
+import type { DeviceError } from "@know-meet/application";
+import type { DeviceKind } from "@know-meet/domain";
+import { DEVICE_NOUN } from "./device-options";
+
+export const DEVICE_COPY = {
+  permissionHint: "Allow camera and microphone to choose a device.",
+  noDeviceHint: "Connect one and it appears here.",
+  paneTitle: "Audio and video",
+  paneLede: "Only you see these settings.",
+  paneClose: "Close audio and video settings",
+  paneBody: "Audio and video settings",
+  audioHeading: "Audio",
+  videoHeading: "Video",
+  speakerUnsupported:
+    "This browser plays meeting audio through your system’s sound output. To change it, use your computer’s sound settings.",
+  testSound: "Play test sound",
+  testSoundPlaying: "Playing…",
+  cameraOff: "Your camera is off",
+  previewLabel: "Your camera preview",
+} as const;
+
+/** The option a select shows before the browser lists any device of its kind. */
+export function placeholderOption(kind: DeviceKind): string {
+  return kind === "microphone"
+    ? "Default microphone"
+    : kind === "camera"
+      ? "Default camera"
+      : "Default speaker";
+}
+
+export function noDeviceOption(kind: DeviceKind): string {
+  return `No ${DEVICE_NOUN[kind].toLowerCase()} found`;
+}
+
+export function deviceChanged(kind: DeviceKind, label: string): string {
+  return `${DEVICE_NOUN[kind]} changed to ${label}.`;
+}
+
+export function deviceDisconnected(label: string, fallback: string): string {
+  return `${label} disconnected. Using ${fallback}.`;
+}
+
+export function deviceBlocked(kind: DeviceKind): string {
+  return `${DEVICE_NOUN[kind]} blocked by the browser. Allow it in the address bar’s site settings, then reopen this panel.`;
+}
+
+/** The line under a select whose switch did not take; the select is back on the previous device. */
+export function switchFailed(label: string, error?: DeviceError): string {
+  if (error?.code === "device-not-found") {
+    return `Couldn’t use ${label}. It’s no longer connected. Choose another device.`;
+  }
+  if (error?.code === "permission-denied") {
+    return `Couldn’t use ${label}. The browser blocked it. Allow it in the address bar’s site settings, then try again.`;
+  }
+  if (error?.code === "connection-lost") {
+    return `Couldn’t use ${label} because you’re not connected. Wait for the connection to come back, then try again.`;
+  }
+  return `Couldn’t use ${label}. Another app may be using it. Close it and try again.`;
+}
diff --git a/apps/web/src/presentation/guest-meeting/devices/device-field.tsx b/apps/web/src/presentation/guest-meeting/devices/device-field.tsx
new file mode 100644
index 00000000..2d7403ed
--- /dev/null
+++ b/apps/web/src/presentation/guest-meeting/devices/device-field.tsx
@@ -0,0 +1,114 @@
+// TJ-ARCH-MOB-001 compliant
+// One device picker (device-settings shape, sections 5 and 6; DS-1, DS-7, DS-8): a visible
+// label bound to a native <select> (the OS list reads long device names best), then one
+// line under it, the hint or the error. Native selects are 48px tall on `control`, focus is
+// the `focus` fill (kit NativeSelect, Flat 2.0). Modes:
+// - ready: lists the devices; a change switches at once (no Apply).
+// - locked: before permission. aria-disabled, still focusable, described by the hint; it
+//   ignores changes and does not open.
+// - none: no device of this kind. Disabled, one option "No <kind> found", with the hint.
+// A failed switch sets aria-invalid (the `control-invalid` fill) and the error line, which
+// carries an alert icon so the state is never colour alone.
+import { KmIcon } from "@know-meet/ui/components/km-icon";
+import { NativeSelect, NativeSelectOption } from "@know-meet/ui/components/native-select";
+import type * as React from "react";
+import type { DeviceOption } from "./device-options";
+
+export type DeviceFieldMode = "ready" | "locked" | "none";
+
+interface DeviceFieldProps {
+  readonly id: string;
+  readonly label: string;
+  readonly mode: DeviceFieldMode;
+  readonly options: readonly DeviceOption[];
+  /** The option shown; empty when nothing is listed. */
+  readonly value: string;
+  /** Shown when the list is empty (before the browser lists devices, or none found). */
+  readonly emptyOption: string;
+  readonly hint: string | null;
+  readonly error: string | null;
+  readonly onChange: (value: string) => void;
+  readonly testId?: string;
+}
+
+/** Keys that would move a native select's value or open it while it is locked. */
+const LOCKED_KEYS = new Set([
+  "ArrowUp",
+  "ArrowDown",
+  "Home",
+  "End",
+  "PageUp",
+  "PageDown",
+  " ",
+  "Enter",
+]);
+
+export function DeviceField({
+  id,
+  label,
+  mode,
+  options,
+  value,
+  emptyOption,
+  hint,
+  error,
+  onChange,
+  testId,
+}: DeviceFieldProps) {
+  const locked = mode === "locked";
+  const lineId = `${id}-line`;
+  const line = error ?? hint;
+  const listed = mode === "ready" && options.length > 0;
+
+  const guard = (event: React.KeyboardEvent<HTMLSelectElement>) => {
+    if (locked && LOCKED_KEYS.has(event.key)) event.preventDefault();
+  };
+
+  return (
+    <div className="grid gap-1.5">
+      <label htmlFor={id} className="text-sm font-semibold text-foreground">
+        {label}
+      </label>
+      <NativeSelect
+        id={id}
+        data-testid={testId}
+        value={listed ? value : ""}
+        disabled={mode === "none"}
+        aria-disabled={locked ? true : undefined}
+        aria-invalid={error === null ? undefined : true}
+        aria-describedby={line === null ? undefined : lineId}
+        onKeyDown={guard}
+        onMouseDown={(event) => {
+          if (locked) event.preventDefault();
+        }}
+        onChange={(event) => {
+          if (!locked) onChange(event.target.value);
+        }}
+        className="has-[select[aria-disabled=true]]:opacity-50"
+      >
+        {listed ? (
+          options.map((option) => (
+            <NativeSelectOption key={option.value} value={option.value}>
+              {option.label}
+            </NativeSelectOption>
+          ))
+        ) : (
+          <NativeSelectOption value="">{emptyOption}</NativeSelectOption>
+        )}
+      </NativeSelect>
+      {line === null ? null : (
+        <p
+          id={lineId}
+          className={
+            error === null
+              ? "text-sm text-muted-foreground"
+              : "flex items-start gap-1.5 text-sm text-red-text"
+          }
+        >
+          {error === null ? null : <KmIcon name="alert" className="mt-0.5 size-4 flex-none" />}
+          <span>{line}</span>
+        </p>
+      )}
+    </div>
+  );
+}
diff --git a/apps/web/src/presentation/guest-meeting/devices/device-options.ts b/apps/web/src/presentation/guest-meeting/devices/device-options.ts
new file mode 100644
index 00000000..3ed0395c
--- /dev/null
+++ b/apps/web/src/presentation/guest-meeting/devices/device-options.ts
@@ -0,0 +1,85 @@
+// TJ-ARCH-MOB-001 compliant
+// What a device select lists and shows, derived from the room's device list (no React, no
+// browser calls). Option values are the browser's device ids (scenario contract WC-5, WC-6).
+// The entry the browser marks as the system default reads "Default (<label>)", or "System
+// default" when the browser gives no label (device-settings shape, section 7).
+import {
+  type DeviceId,
+  type DeviceKind,
+  devicesOfKind,
+  hasDevice,
+  type MediaDevice,
+} from "@know-meet/domain";
+
+export interface DeviceOption {
+  readonly value: DeviceId;
+  readonly label: string;
+}
+
+export const DEVICE_NOUN: Readonly<Record<DeviceKind, string>> = {
+  microphone: "Microphone",
+  camera: "Camera",
+  speaker: "Speaker",
+};
+
+/** Chrome prefixes its default entry ("Default - Built-in Microphone"); the option adds its own. */
+const BROWSER_DEFAULT_PREFIX = /^default\s*[-–:]\s*/i;
+
+function optionLabel(device: MediaDevice, position: number): string {
+  const label = device.label.replace(BROWSER_DEFAULT_PREFIX, "").trim();
+  if (device.isDefault) return label === "" ? "System default" : `Default (${label})`;
+  return label === "" ? `${DEVICE_NOUN[device.kind]} ${position}` : label;
+}
+
+export function deviceOptions(
+  devices: readonly MediaDevice[],
+  kind: DeviceKind,
+): readonly DeviceOption[] {
+  return devicesOfKind(devices, kind).map((device, index) => ({
+    value: device.id,
+    label: optionLabel(device, index + 1),
+  }));
+}
+
+/** Labels appear only once the site may use that kind of device. */
+export function hasDevicePermission(devices: readonly MediaDevice[], kind: DeviceKind): boolean {
+  return devicesOfKind(devices, kind).some((device) => device.label !== "");
+}
+
+/** The entry the browser marks as default, else the first it lists (the browser's own default). */
+export function defaultDevice(
+  devices: readonly MediaDevice[],
+  kind: DeviceKind,
+): MediaDevice | null {
+  const ofKind = devicesOfKind(devices, kind);
+  return ofKind.find((device) => device.isDefault) ?? ofKind[0] ?? null;
+}
+
+/**
+ * The value a select shows: the chosen or active device while it is listed, otherwise the
+ * default (a device that was unplugged falls back). Empty when nothing is listed.
+ */
+export function shownDeviceId(
+  devices: readonly MediaDevice[],
+  kind: DeviceKind,
+  id: DeviceId | null,
+): DeviceId | "" {
+  if (id !== null && hasDevice(devices, kind, id)) return id;
+  return defaultDevice(devices, kind)?.id ?? "";
+}
+
+/** The label people read for a device id, as its option shows it. */
+export function deviceLabel(devices: readonly MediaDevice[], kind: DeviceKind, id: string): string {
+  const option = deviceOptions(devices, kind).find((candidate) => candidate.value === id);
+  return option?.label ?? DEVICE_NOUN[kind].toLowerCase();
+}
+
+/** Narrows a select's value to one of its listed device ids. */
+export function listedDeviceId(
+  devices: readonly MediaDevice[],
+  kind: DeviceKind,
+  value: string,
+): DeviceId | null {
+  const device = devicesOfKind(devices, kind).find((candidate) => candidate.id === value);
+  return device?.id ?? null;
+}
diff --git a/apps/web/src/presentation/guest-meeting/devices/level-meter.tsx b/apps/web/src/presentation/guest-meeting/devices/level-meter.tsx
