+// TJ-ARCH-MOB-001 compliant
+// The "Audio" section of the room's "Audio and video" pane (wc05 task 5.2; WC-5, WC-6,
+// WC-13): Microphone picker, its level meter, then Speaker. Where the browser can choose
+// an output (support.speakerSelection) the Speaker picker and "Play test sound" show;
+// otherwise a neutral note under the Speaker heading explains that the system output is
+// used, in a role="status" element so it is announced once when the pane opens (DS-5,
+// DS-6). A microphone the browser blocked shows the reason instead of the picker.
+// Scenario contract: km-settings-mic-select, km-settings-speaker-select,
+// km-speaker-unsupported.
+import type { ConferencingSupport, DeviceId } from "@know-meet/domain";
+import { Button } from "@know-meet/ui/components/button";
+import { KmIcon } from "@know-meet/ui/components/km-icon";
+import { DEVICE_COPY, deviceBlocked } from "../../../guest-meeting/devices/device-copy";
+import { DeviceField } from "../../../guest-meeting/devices/device-field";
+import { LevelMeter } from "../../../guest-meeting/devices/level-meter";
+import type { RoomDevice } from "./use-room-device";
+import { useTestSound } from "./use-test-sound";
+
+export const sectionHeadingClass = "font-display text-base font-semibold";
+
+interface AudioSectionProps {
+  readonly microphone: RoomDevice;
+  readonly speaker: RoomDevice;
+  /** The speaker in use, for the test sound; null plays through the default output. */
+  readonly speakerId: DeviceId | null;
+  readonly support: ConferencingSupport;
+  readonly micBlocked: boolean;
+  /** The pane's own capture of the microphone in use; null while closed or muted. */
+  readonly micStream: MediaStream | null;
+  readonly micOn: boolean;
+}
+
+/** DS-10: 44px on touch, the 36px `sm` size only under a fine pointer. */
+const testSoundClass = "w-fit [@media(pointer:coarse)]:min-h-size-target";
+
+export function AudioSection({
+  microphone,
+  speaker,
+  speakerId,
+  support,
+  micBlocked,
+  micStream,
+  micOn,
+}: AudioSectionProps) {
+  const sound = useTestSound(speakerId);
+  const speakerSupported = support.speakerSelection === "supported";
+  return (
+    <section aria-labelledby="settings-audio-heading" className="grid gap-s3">
+      <h3 id="settings-audio-heading" className={sectionHeadingClass}>
+        {DEVICE_COPY.audioHeading}
+      </h3>
+      {micBlocked ? (
+        <p className="text-sm text-foreground">{deviceBlocked("microphone")}</p>
+      ) : (
+        <>
+          <DeviceField
+            id="settings-microphone"
+            testId="km-settings-mic-select"
+            label="Microphone"
+            {...microphone}
+          />
+          <LevelMeter stream={micStream} hidden={!micOn} />
+        </>
+      )}
+      {speakerSupported ? (
+        <>
+          <DeviceField
+            id="settings-speaker"
+            testId="km-settings-speaker-select"
+            label="Speaker"
+            {...speaker}
+          />
+          <Button
+            type="button"
+            variant="secondary"
+            size="sm"
+            aria-disabled={sound.playing ? true : undefined}
+            onClick={() => {
+              if (!sound.playing) sound.play();
+            }}
+            className={testSoundClass}
+          >
+            <KmIcon name="speaker" />
+            {sound.playing ? DEVICE_COPY.testSoundPlaying : DEVICE_COPY.testSound}
+          </Button>
+        </>
+      ) : (
+        <div className="grid gap-1.5">
+          <h4 className="text-sm font-semibold text-foreground">Speaker</h4>
+          <div
+            role="status"
+            data-testid="km-speaker-unsupported"
+            className="flex items-start gap-s2 rounded-base bg-surface p-s3 text-sm text-foreground"
+          >
+            <KmIcon name="info" className="mt-0.5 size-4 flex-none text-muted-foreground" />
+            <span>{DEVICE_COPY.speakerUnsupported}</span>
+          </div>
+        </div>
+      )}
+    </section>
+  );
+}
diff --git a/apps/web/src/presentation/meeting-room/presentation/device-settings/device-settings-pane.tsx b/apps/web/src/presentation/meeting-room/presentation/device-settings/device-settings-pane.tsx
new file mode 100644
index 00000000..c54f9524
--- /dev/null
+++ b/apps/web/src/presentation/meeting-room/presentation/device-settings/device-settings-pane.tsx
@@ -0,0 +1,112 @@
+// TJ-ARCH-MOB-001 compliant
+// The room sheet's "Audio and video" pane (wc05 task 5.2, wc07 task 7.3; device-settings
+// shape "Pane anatomy"): the head (title, "Only you see these settings.", Close), then
+// Audio (Microphone, level meter, Speaker or the unsupported note, Play test sound) and
+// Video (Camera, self preview, Background). Opening it moves focus to the title; Escape or
+// Close returns focus to the Settings control (use-room-sheet). The self preview and the
+// meter's own capture run only while the pane is open. A device in use that is unplugged
+// falls back to the default and says so in a toast (which announces it politely).
+// Focus order (DS-3): Close, Microphone, Speaker, Play test sound, Camera, Background.
+import type { ConferencingUseCases, RealtimeRoom, RoomSnapshot } from "@know-meet/application";
+import type { TrackKind } from "@know-meet/domain";
+import { toast } from "@know-meet/ui/components/toast";
+import { useCallback, useEffect } from "react";
+import { DEVICE_COPY } from "../../../guest-meeting/devices/device-copy";
+import { deviceOptions, hasDevicePermission } from "../../../guest-meeting/devices/device-options";
+import type { Announce } from "../../../guest-meeting/live-status";
+import { BackgroundSection } from "../background/background-section";
+import { paneTitleId } from "../room-sheet/room-sheet";
+import { RoomSheetPane } from "../room-sheet/room-sheet-pane";
+import { AudioSection } from "./audio-section";
+import { usePaneMicStream } from "./use-pane-mic-stream";
+import { useRoomDevice } from "./use-room-device";
+import { VideoSection } from "./video-section";
+
+interface DeviceSettingsPaneProps {
+  readonly room: RealtimeRoom;
+  readonly snapshot: RoomSnapshot;
+  readonly conferencing: ConferencingUseCases;
+  readonly announce: Announce;
+  /** Devices the browser refused at join (from the room URL). */
+  readonly blockedAtJoin: readonly TrackKind[];
+  /** Settings is the sheet's current pane (open or closing). */
+  readonly shown: boolean;
+  /** The sheet is open on this pane. */
+  readonly active: boolean;
+  readonly onClose: () => void;
+}
+
+export function DeviceSettingsPane({
+  room,
+  snapshot,
+  conferencing,
+  announce,
+  blockedAtJoin,
+  shown,
+  active,
+  onClose,
+}: DeviceSettingsPaneProps) {
+  const { devices, local, support } = snapshot;
+  const notifyLost = useCallback((message: string) => {
+    toast.add({ title: message });
+  }, []);
+  const microphone = useRoomDevice("microphone", devices, conferencing, announce, notifyLost);
+  const camera = useRoomDevice("camera", devices, conferencing, announce, notifyLost);
+  const speaker = useRoomDevice("speaker", devices, conferencing, announce, notifyLost);
+
+  useEffect(() => {
+    if (active) document.getElementById(paneTitleId("settings"))?.focus({ preventScroll: true });
+  }, [active]);
+
+  const blocked = (kind: TrackKind) =>
+    blockedAtJoin.includes(kind) && !hasDevicePermission(devices.available, kind);
+  const micBlocked = blocked("microphone");
+  const cameraBlocked = blocked("camera");
+  const micOn = local !== null && !local.microphone.muted;
+  const cameraOn = local !== null && !local.camera.muted;
+  const micStream = usePaneMicStream(active && micOn && !micBlocked, devices.active.microphone);
+  const noCamera =
+    cameraBlocked ||
+    (hasDevicePermission(devices.available, "camera") &&
+      deviceOptions(devices.available, "camera").length === 0);
+
+  return (
+    <RoomSheetPane
+      pane="settings"
+      shown={shown}
+      title={DEVICE_COPY.paneTitle}
+      lede={DEVICE_COPY.paneLede}
+      closeLabel={DEVICE_COPY.paneClose}
+      onClose={onClose}
+      bodyLabel={DEVICE_COPY.paneBody}
+    >
+      <div className="grid gap-s5 pt-s2">
+        <AudioSection
+          microphone={microphone}
+          speaker={speaker}
+          speakerId={devices.active.speaker}
+          support={support}
+          micBlocked={micBlocked}
+          micStream={micStream}
+          micOn={micOn}
+        />
+        <VideoSection
+          room={room}
+          local={local}
+          camera={camera}
+          cameraBlocked={cameraBlocked}
+          open={active}
+        >
+          <BackgroundSection
+            state={snapshot.backgroundEffect}
+            support={support.backgroundEffects}
+            cameraOn={cameraOn}
+            noCamera={noCamera}
+            conferencing={conferencing}
+            announce={announce}
+          />
+        </VideoSection>
+      </div>
+    </RoomSheetPane>
+  );
+}
