diff --git a/apps/web/src/presentation/meeting-room/presentation/device-settings/use-pane-mic-stream.ts b/apps/web/src/presentation/meeting-room/presentation/device-settings/use-pane-mic-stream.ts
new file mode 100644
index 00000000..c59d0aaf
--- /dev/null
+++ b/apps/web/src/presentation/meeting-room/presentation/device-settings/use-pane-mic-stream.ts
@@ -0,0 +1,50 @@
+// TJ-ARCH-MOB-001 compliant
+// The audio the "Audio and video" pane's level meter measures (device-settings shape,
+// section 8: "The pane's self preview and meter run only while the pane is open"). The
+// room never hands out its published microphone (the port does not play or expose it), so
+// the pane opens its own audio-only capture of the device in use, and only while the pane
+// is open and the microphone is on. It follows device switches and stops when the pane
+// closes. If the browser cannot open the device a second time, the meter shows silence;
+// the meeting audio itself is not affected.
+import type { DeviceId } from "@know-meet/domain";
+import { useEffect, useState } from "react";
+
+function stop(stream: MediaStream | null): void {
+  for (const track of stream?.getTracks() ?? []) track.stop();
+}
+
+export function usePaneMicStream(
+  listening: boolean,
+  deviceId: DeviceId | null,
+): MediaStream | null {
+  const [stream, setStream] = useState<MediaStream | null>(null);
+
+  useEffect(() => {
+    const media = navigator.mediaDevices;
+    if (!listening || media === undefined) return undefined;
+    let cancelled = false;
+    let owned: MediaStream | null = null;
+    const audio: MediaTrackConstraints | boolean =
+      deviceId === null ? true : { deviceId: { exact: deviceId } };
+    media.getUserMedia({ audio, video: false }).then(
+      (next) => {
+        if (cancelled) {
+          stop(next);
+          return;
+        }
+        owned = next;
+        setStream(next);
+      },
+      () => {
+        if (!cancelled) setStream(null);
+      },
+    );
+    return () => {
+      cancelled = true;
+      stop(owned);
+      setStream(null);
+    };
+  }, [listening, deviceId]);
+
+  return stream;
+}
diff --git a/apps/web/src/presentation/meeting-room/presentation/device-settings/use-room-device.ts b/apps/web/src/presentation/meeting-room/presentation/device-settings/use-room-device.ts
new file mode 100644
index 00000000..ca2bdd7e
--- /dev/null
+++ b/apps/web/src/presentation/meeting-room/presentation/device-settings/use-room-device.ts
@@ -0,0 +1,103 @@
+// TJ-ARCH-MOB-001 compliant
+// One room device picker's state (wc05 task 5.2; device-settings shape, room column of
+// "States"). A change switches through the conferencing use case at once; the select shows
+// the requested device while the switch runs (the published track keeps its last frame),
+// then whatever the room reports. Success is announced politely ("Microphone changed to
+// <label>."); a refusal returns the select to the device in use and sets the error line.
+// The device in use being unplugged falls back to the default (the adapter switches) and
+// is reported through `onLost`, which the pane shows as a toast.
+import type { ConferencingUseCases, DeviceState } from "@know-meet/application";
+import type { DeviceId, DeviceKind } from "@know-meet/domain";
+import { useCallback, useState } from "react";
+import {
+  DEVICE_COPY,
+  deviceChanged,
+  deviceDisconnected,
+  noDeviceOption,
+  placeholderOption,
+  switchFailed,
+} from "../../../guest-meeting/devices/device-copy";
+import type { DeviceFieldMode } from "../../../guest-meeting/devices/device-field";
+import {
+  type DeviceOption,
+  deviceLabel,
+  deviceOptions,
+  hasDevicePermission,
+  listedDeviceId,
+  shownDeviceId,
+} from "../../../guest-meeting/devices/device-options";
+import { useDeviceLoss } from "../../../guest-meeting/devices/use-device-loss";
+import type { Announce } from "../../../guest-meeting/live-status";
+
+export interface RoomDevice {
+  readonly mode: DeviceFieldMode;
+  readonly options: readonly DeviceOption[];
+  readonly value: string;
+  readonly emptyOption: string;
+  readonly hint: string | null;
+  readonly error: string | null;
+  readonly onChange: (value: string) => void;
+}
+
+interface Switching {
+  readonly requested: DeviceId | null;
+  readonly error: string | null;
+}
+
+const IDLE: Switching = { requested: null, error: null };
+
+function modeOf(devices: DeviceState, kind: DeviceKind): DeviceFieldMode {
+  if (!hasDevicePermission(devices.available, kind)) return "locked";
+  return deviceOptions(devices.available, kind).length === 0 ? "none" : "ready";
+}
+
+export function useRoomDevice(
+  kind: DeviceKind,
+  devices: DeviceState,
+  conferencing: ConferencingUseCases,
+  announce: Announce,
+  onLost: (message: string) => void,
+): RoomDevice {
+  const { available, active } = devices;
+  const [switching, setSwitching] = useState<Switching>(IDLE);
+  const value = shownDeviceId(available, kind, switching.requested ?? active[kind]);
+
+  useDeviceLoss(available, kind, active[kind], (lostLabel) => {
+    const fallback = deviceLabel(available, kind, shownDeviceId(available, kind, null));
+    onLost(deviceDisconnected(lostLabel, fallback));
+  });
+
+  const onChange = useCallback(
+    (next: string) => {
+      const id = listedDeviceId(available, kind, next);
+      if (id === null || id === value) return;
+      const label = deviceLabel(available, kind, id);
+      setSwitching({ requested: id, error: null });
+      void conferencing.selectDevice(kind, id).then((result) => {
+        if (result.ok) {
+          setSwitching(IDLE);
+          announce(deviceChanged(kind, label));
+          return;
+        }
+        setSwitching({ requested: null, error: switchFailed(label, result.error) });
+      });
+    },
+    [available, kind, value, conferencing, announce],
+  );
+
+  const mode = modeOf(devices, kind);
+  return {
+    mode,
+    options: deviceOptions(available, kind),
+    value,
+    emptyOption: mode === "none" ? noDeviceOption(kind) : placeholderOption(kind),
+    hint:
+      mode === "locked"
+        ? DEVICE_COPY.permissionHint
+        : mode === "none"
+          ? DEVICE_COPY.noDeviceHint
+          : null,
+    error: switching.error,
+    onChange,
+  };
+}
diff --git a/apps/web/src/presentation/meeting-room/presentation/device-settings/use-test-sound.ts b/apps/web/src/presentation/meeting-room/presentation/device-settings/use-test-sound.ts
new file mode 100644
index 00000000..d780604e
--- /dev/null
+++ b/apps/web/src/presentation/meeting-room/presentation/device-settings/use-test-sound.ts
@@ -0,0 +1,74 @@
+// TJ-ARCH-MOB-001 compliant
+// "Play test sound" (device-settings shape, "Speaker supported"): a short, soft tone played
+// through the chosen output, so people hear which speaker the meeting uses. The tone is
+// generated (no audio file), routed to an <audio> element whose sink is the chosen speaker,
+// and lasts 1.5 s; the button reads "Playing…" meanwhile. Offered only where the browser
+// can choose a speaker (setSinkId), so the sink is always settable here.
+import type { DeviceId } from "@know-meet/domain";
+import { useCallback, useEffect, useRef, useState } from "react";
+
+const TONE_MS = 1500;
+const TONE_HZ = 660;
+const TONE_GAIN = 0.15;
+const FADE_S = 0.05;
+
+interface SinkSelectable {
+  setSinkId(sinkId: string): Promise<void>;
+}
+
+function canSelectSink(element: HTMLMediaElement): element is HTMLMediaElement & SinkSelectable {
+  return "setSinkId" in element && typeof element.setSinkId === "function";
+}
+
+export interface TestSound {
+  readonly playing: boolean;
+  readonly play: () => void;
+}
+
+export function useTestSound(speaker: DeviceId | null): TestSound {
+  const [playing, setPlaying] = useState(false);
+  const stopRef = useRef<(() => void) | null>(null);
+  useEffect(() => () => stopRef.current?.(), []);
+
+  const play = useCallback(() => {
+    if (stopRef.current !== null) return;
+    const context = new AudioContext();
+    const oscillator = context.createOscillator();
+    const gain = context.createGain();
+    const output = context.createMediaStreamDestination();
+    const element = new Audio();
+    const seconds = TONE_MS / 1000;
+    oscillator.frequency.value = TONE_HZ;
+    gain.gain.setValueAtTime(0, context.currentTime);
+    gain.gain.linearRampToValueAtTime(TONE_GAIN, context.currentTime + FADE_S);
+    gain.gain.setValueAtTime(TONE_GAIN, context.currentTime + seconds - FADE_S);
+    gain.gain.linearRampToValueAtTime(0, context.currentTime + seconds);
+    oscillator.connect(gain).connect(output);
+    element.srcObject = output.stream;
+
+    let timer = 0;
+    const stop = () => {
+      window.clearTimeout(timer);
+      stopRef.current = null;
+      element.pause();
+      element.srcObject = null;
+      void context.close();
+      setPlaying(false);
+    };
+    stopRef.current = stop;
+    setPlaying(true);
+
+    const sink =
+      speaker !== null && canSelectSink(element) ? element.setSinkId(speaker) : Promise.resolve();
+    sink
+      .then(() => element.play())
+      .then(() => {
+        oscillator.start();
+        oscillator.stop(context.currentTime + seconds);
+        timer = window.setTimeout(stop, TONE_MS);
+      })
+      .catch(stop);
+  }, [speaker]);
+
+  return { playing, play };
+}
diff --git a/apps/web/src/presentation/meeting-room/presentation/device-settings/video-section.tsx b/apps/web/src/presentation/meeting-room/presentation/device-settings/video-section.tsx
